// Picking which caption track to save, from the InnerTube player response.
//
// Transcripts are saved in English only (owner's choice, 2026-10-17). Videos with YouTube's AI
// auto-dubbing list an auto-generated track for every dubbed language, sorted by name, so the
// first auto-generated track can be Arabic on an English video. The player response says which
// track belongs to the original audio (`audioTracks[default].captionTrackIndices[0]`).

export interface CaptionTrack {
  baseUrl: string;
  languageCode: string;
  /** `asr` for auto-generated captions; absent for captions someone wrote. */
  kind?: string;
  name?: { simpleText?: string; runs?: { text: string }[] };
  vssId?: string;
}

/** The track to fetch, and whether YouTube must machine-translate it into English. */
export interface CaptionChoice {
  track: CaptionTrack;
  translate: boolean;
}

export const TRANSCRIPT_LANGUAGE = "en";

export function isAutoGenerated(track: CaptionTrack): boolean {
  return track.kind === "asr";
}

function baseLanguage(code: string): string {
  return code.toLowerCase().replace(/_/g, "-").split("-")[0]!;
}

function isEnglish(track: CaptionTrack): boolean {
  return baseLanguage(track.languageCode) === TRANSCRIPT_LANGUAGE;
}

/**
 * The English track to save:
 * 1. captions someone wrote in English (the original audio's track first, then plain `en`),
 * 2. auto-generated English, the original audio's track first (on a dubbed video another
 *    English track transcribes the English dub, which is still English),
 * 3. otherwise the original audio's track (or the first written one), machine-translated into
 *    English by YouTube.
 *
 * `originalIndex` is the index into `tracks` of the original audio's captions, when known.
 */
export function chooseCaptionTrack(
  tracks: CaptionTrack[],
  originalIndex?: number,
): CaptionChoice | null {
  const usable = tracks.filter((track) => track.baseUrl && track.languageCode);
  if (usable.length === 0) return null;

  const candidate = originalIndex !== undefined ? tracks[originalIndex] : undefined;
  const original = candidate && usable.includes(candidate) ? candidate : undefined;
  const written = usable.filter((track) => !isAutoGenerated(track));
  const auto = usable.filter(isAutoGenerated);

  const writtenEnglish = written.filter(isEnglish);
  const english =
    (original && writtenEnglish.includes(original) ? original : undefined) ??
    writtenEnglish.find((track) => track.languageCode.toLowerCase() === TRANSCRIPT_LANGUAGE) ??
    writtenEnglish[0] ??
    (original && isAutoGenerated(original) && isEnglish(original) ? original : undefined) ??
    auto.find(isEnglish);
  if (english) return { track: english, translate: false };

  const source = original ?? written[0] ?? auto[0]!;
  return { track: source, translate: true };
}

/** The timedtext address in the default XML form (`fmt=srv3` taken out), translated if asked. */
export function timedTextUrl(track: CaptionTrack, translateTo?: string): string {
  const url = track.baseUrl.replace(/&fmt=[^&]*/g, "").replace(/\?fmt=[^&]*&?/, "?");
  return translateTo ? `${url}&tlang=${encodeURIComponent(translateTo)}` : url;
}
